namespace generic.util;








public class FileLocker {

	private static readonly string META_TAG = "<META> ";
	private static readonly string LOCK_TYPE_KEY = META_TAG + "Supports File Channel Locking";
	private static readonly string FILE_LOCK_TYPE = "File Lock";
	private static readonly string[] PROPERTY_KEYS = new string[] { "Username", "Hostname", "Timestamp", "OS Name", "OS Architecture", "OS Version" };
	private static readonly DateFormat DATE_FORMAT = new SimpleDateFormat();

	protected File lockFile;
	protected Properties existingLockProperties;
	protected Properties createdLockProperties;
	protected string existingLockType;
	protected bool isLocked;

	protected FileLocker(File lockFile) {
		this.lockFile = lockFile;

		existingLockProperties = loadExistingLockFile();
		if (existingLockProperties != null) {
			existingLockType = existingLockProperties.getProperty(LOCK_TYPE_KEY);
		}
		else {
			existingLockType = null;
		}
	}

	public bool @lock() {
		if (existingLockProperties == null) {
			return createLockFile();
		}

		// can't create a primitive lock if one already exists
		return false;
	}

	public bool isLocked() {
		return isLocked;
	}

	public void release() {
		if (isLockOwner()) {
			lockFile.delete();
		}
		isLocked = false;
	}

	public bool canForceLock() {
		return FILE_LOCK_TYPE.equals(existingLockType);
	}

	public bool forceLock() {
		if (canForceLock()) {
			return createLockFile();
		}
		return false;
	}

	private Properties loadExistingLockFile() {
		if (!lockFile.exists()) {
			return null;
		}

		Properties properties = new Properties();

		try
{
    using (InputStream @is = new FileInputStream(lockFile))
    {

			properties.load(@is);
			return properties;
		
    }
}
		catch (FileNotFoundException e) {
			// should not happen
		}
		catch (IOException e) {
			// ignore
		}
		return null;
	}

	public string getExistingLockFileInformation() {
		if (existingLockProperties == null) {
			return "no properties in lock file";
		}

		StringBuilder buf = new StringBuilder("<p><table border=0>");
		foreach (string name in PROPERTY_KEYS) {
			buf.append("<tr><td>");
			buf.append("&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;");
			buf.append(name);
			buf.append(": ");
			buf.append("</td><td>");
			buf.append(existingLockProperties.get(name).toString());
			buf.append("</td></tr>");
		}
		buf.append("</table>");
		return buf.toString();
	}

	protected string getLockType() {
		return FILE_LOCK_TYPE;
	}

	protected bool createLockFile() {
		Properties properties = new Properties();

		// user info
		properties.put("Username", System.getProperty("user.name"));
		string hostname = "<Unknown>";
		try {
			hostname = InetAddress.getLocalHost().getHostName();
		}
		catch (UnknownHostException e) {
			// use default
		}
		properties.put("Hostname", hostname);

		properties.put("Timestamp", DATE_FORMAT.format(new Date()));

		// system info
		properties.put("OS Name", System.getProperty("os.name"));
		properties.put("OS Architecture", System.getProperty("os.arch"));
		properties.put("OS Version", System.getProperty("os.version"));

		// meta info
		properties.put(LOCK_TYPE_KEY, getLockType());

		// store the data
		if (!storeProperties(properties)) {
			return false;
		}

		if (lockFile.exists()) {
			createdLockProperties = properties;
			isLocked = true;
			return true;
		}
		return false;
	}

	private bool storeProperties(Properties properties) {

		try
{
    using (OutputStream os = new FileOutputStream(lockFile))
    {

			properties.store(os, "Ghidra Lock File");
			return true;
		
    }
}
		catch (IOException e) {
			return false;
		}
	}

	private bool isLockOwner() {
		if (createdLockProperties == null) {
			return false; // we never created a lock file
		}

		Properties currentLockProperties = loadExistingLockFile();
		if (currentLockProperties == null) {
			return false; // no lock file, someone deleted ours
		}

		foreach (string key in PROPERTY_KEYS) {
			string originalProperty = createdLockProperties.getProperty(key);
			string currentProperty = currentLockProperties.getProperty(key);
			if (!Objects.equals(originalProperty, currentProperty)) {
				return false;
			}
		}
		return true;
	}

	/* @Override */
	public string toString() {
		return getClass().getSimpleName() + lockFile;
	}
}
